        if (contentInfo?.mode === 'content_addressed_packs' && Array.isArray(contentInfo.packRefs) && contentInfo.packRefs.length > 0) {
            contentInfo.packRefs.forEach((ref) => pushFile({
                path: ref.path,
                role: 'vector_pack',
                indexId: manifest.indexId,
                checksum: ref.checksum,
            }));
        }
