                    return true;
                const legacyStandard = readLegacyStandardData_ACU(message);
                if (legacyStandard && Object.keys(legacyStandard).some(k => k.startsWith('sheet_')))
                    return true;
                const legacySummary = readLegacySummaryData_ACU(message);
