        const bm25CacheKey = `${state.manifest?.storageIdentity?.writeGeneration || 'legacy'}::${state.manifest?.indexId || ''}::${searchableCandidates
        .map((candidate) => candidate.chunk.textHash || candidate.chunk.chunkId || candidate.chunk.text)
        .join('|')}`;
